def page(file,title,body,desc='Sustainability reporting, ESG data and reporting controls. Explore Min Gao’s research and independent portfolio work.'):
    links=''.join(f'<a href="{f}"'+(' aria-current="page"' if f==file else '')+f'>{label}</a>' for f,label in nav)
    html=f'''<!doctype html><html lang="en-GB"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>{escape(title)} | Min Gao</title><meta name="description" content="{escape(desc)}"><meta name="theme-color" content="#252c26"><meta property="og:title" content="{escape(title)} | Min Gao"><meta property="og:description" content="{escape(desc)}"><meta property="og:type" content="website"><link rel="icon" type="image/svg+xml" href="assets/brand-mark.svg"><link rel="stylesheet" href="assets/styles.css"><script defer src="assets/main.js"></script></head><body class="page-{file[:-5]}"><a class="skip" href="#main">Skip to content</a><header class="header"><div class="wrap nav"><a class="brand" href="index.html" aria-label="Min Gao home"><img class="brand-mark" src="assets/brand-mark.svg" alt="" width="64" height="64"></a><nav class="navlinks" id="navigation" aria-label="Main navigation">{links}</nav><a class="cv-link" href="cv.html">View CV ↗</a><button class="menu" aria-controls="navigation" aria-expanded="false" type="button">Menu</button></div></header><main id="main">{body}</main><footer class="footer"><div class="wrap"><span>Oxford, United Kingdom</span><span>© 2026 · Sustainability reporting & ESG data</span><a href="contact.html">Get in touch ↗</a></div></footer></body></html>'''
    (SITE/file).write_text(html)
def visual(kind):
    if kind=='close': return '<div class="document-art"><div class="document-back"></div><div class="document-front"><div class="document-title"><span>REPORTING CLOSE</span><span>01 / 04</span></div><h4>Environmental<br>KPI control register</h4><div class="doc-rule"></div><div class="doc-row"><span>Reporting boundary</span><i></i></div><div class="doc-row"><span>Source & methodology</span><i></i></div><div class="doc-row"><span>Evidence reference</span><i></i></div><div class="doc-row"><span>Review & sign-off</span><i></i></div><div class="doc-foot">INDEPENDENT WORK SAMPLE</div></div><div class="art-label"><span class="tiny-dot"></span> A traceable reporting process</div></div>'
    if kind=='standards': return '<div class="mapping-art"><span class="art-kicker">REQUIREMENT → EVIDENCE</span><div class="mapping-line"><b>01</b><span>Source requirement</span></div><div class="mapping-line"><b>02</b><span>Defined datapoint</span></div><div class="mapping-line"><b>03</b><span>Reviewable evidence</span></div></div>'
    if kind=='research': return '<div class="research-art"><span class="art-kicker">RESEARCH METHODOLOGY</span><div class="research-pages"><span>Source<br>disclosure</span><span>Coding<br>framework</span><span>Documented<br>judgement</span></div><div class="research-caption">A consistent basis for comparison</div></div>'
    return '<div class="mapping-art"><span class="art-kicker">PUBLIC-SOURCE RECONSTRUCTION</span><div class="mapping-line"><b>01</b><span>Impact KPI</span></div><div class="mapping-line"><b>02</b><span>Evidence requirement</span></div><div class="mapping-line"><b>03</b><span>Reporting qualification</span></div></div>'
projects=[('close-pack.html','01 / Independent portfolio','Sustainability reporting close pack','From environmental KPI inputs to an exception log, evidence trail and reviewable release decision.','close'),('interoperability.html','02 / Technical work sample','Standards into reporting controls','A prototype approach to translating disclosure requirements into questions, guidance and validation.','standards'),('research.html','03 / Doctoral research','Corporate disclosure research','A structured, GRI-mapped methodology for reviewing corporate sustainability disclosures.','research'),('b-corp.html','04 / Public-source reconstruction','B Corp impact reporting controls','Reconstructing KPI definitions, proposed ownership and evidence needs from public disclosures.','bcorp')]
def card(p):
 f,tag,title,desc,kind=p
 return f'<article class="card card-{kind}"><div class="card-visual" aria-hidden="true">{visual(kind)}</div><div class="card-body"><p class="eyebrow">{tag}</p><h3>{title}</h3><p>{desc}</p><a class="text-link" href="{f}">Explore case study <span aria-hidden="true">↗</span></a></div></article>'
def heading(label,title,lead):return f'<div class="page-heading"><div class="wrap"><div class="page-hero"><p class="eyebrow">{label}</p><h1>{title}</h1><p class="lead">{lead}</p></div></div></div>'
page('index.html','Sustainability Reporting & ESG Data',f'''<div class="wrap"><section class="hero"><div class="hero-copy"><p class="eyebrow"><span class="eyebrow-line"></span> Professional portfolio</p><h1>Sustainability<br>reporting.<br><em>Built on evidence.</em></h1><p class="hero-description">I connect disclosure requirements with the data, controls and evidence behind dependable reporting.</p><div class="actions"><a class="button" href="work.html">Explore selected work <span aria-hidden="true">↗</span></a><a class="quiet-link" href="about.html">About my approach <span aria-hidden="true">↗</span></a></div><div class="hero-location"><span class="tiny-dot"></span> Oxford, United Kingdom <span class="location-divider">/</span> English & Mandarin</div></div><div class="hero-art" aria-hidden="true"><div class="art-topline"><span>THE REPORTING DISCIPLINE</span><span>MG — 01</span></div>{visual('close')}<div class="hero-art-bottom"><span>From source to sign-off.</span><span>↗</span></div></div></section><div class="credentials-strip"><div><span>Foundation</span><strong>Accounting & finance</strong></div><div><span>Research</span><strong>Corporate sustainability disclosure</strong></div><div><span>Focus</span><strong>Controls & assurance readiness</strong></div></div><section class="section selected-work" id="selected-work"><div class="section-head"><div><p class="eyebrow">01 / Selected work</p><h2>Evidence of the approach.</h2></div><div class="section-intro"><p>Research and independent work samples.<br>Clear methods. Documented limitations.</p><a class="text-link" href="work.html">View all four case studies <span aria-hidden="true">↗</span></a></div></div><div class="cards">{''.join(card(p) for p in projects[:3])}</div></section></div><section class="method-section"><div class="wrap"><div class="section-head"><div><p class="eyebrow">02 / Reporting philosophy</p><h2>A number is only the beginning.</h2></div><p class="section-intro">The useful question is whether someone else can follow the evidence and challenge the judgement.</p></div><ol class="process-rail"><li><span>01</span><h3>Requirement</h3><p>Define the disclosure and reporting boundary.</p></li><li><span>02</span><h3>Data</h3><p>Identify the source and accountable owner.</p></li><li><span>03</span><h3>Controls</h3><p>Validate, reconcile and resolve exceptions.</p></li><li><span>04</span><h3>Evidence</h3><p>Retain a traceable, reviewable reporting trail.</p></li><li><span>05</span><h3>Review & sign-off</h3><p>Support an informed release decision.</p></li></ol><div class="method-bottom"><span>Reporting controls & assurance readiness</span><a href="standards.html">Explore the methodology ↗</a></div></div></section><section class="dark-section"><div class="wrap bridge-layout"><div class="bridge-visual" aria-hidden="true"><span class="bridge-label">A CROSS-BORDER PERSPECTIVE</span><div class="bridge-type">UK<span>↔</span>CN</div><div class="bridge-rule"></div><div class="bridge-captions"><span>Reporting requirements</span><span>Data ownership</span></div></div><div class="bridge-copy"><p class="eyebrow">03 / UK–China reporting</p><h2>Different contexts.<br>A shared evidence trail.</h2><p>Financial-services experience in China. Accounting and finance. UK sustainability-disclosure research.</p><p>A developing specialism in connecting disclosure requirements with data owners, methods and evidence across borders.</p><a class="text-link" href="uk-china.html">Explore the UK–China focus ↗</a></div></div></section><section class="contact-section wrap"><p class="eyebrow">Start a conversation</p><div class="contact-layout"><h2>Better information.<br><em>Better decisions.</em></h2><div><p>Let’s discuss sustainability reporting,<br>ESG data or reporting controls.</p><a class="button" href="contact.html">Get in touch <span aria-hidden="true">↗</span></a></div></div></section>''')
page('work.html','Work Samples',heading('Selected work','Reporting made reviewable.','Executive case studies covering sustainability reporting controls, disclosure methodology and evidence traceability.')+f'<div class="wrap"><p class="note">Independent work samples demonstrate methods and judgement. They are not employer or client delivery, certification or external assurance. Research is labelled separately.</p><div class="work-grid">{"".join(card(p) for p in projects)}</div></div>')
def case(file,title,subtitle,body,kind,outputs,limit):
 page(file,title,heading(kind,title,subtitle)+f'<div class="wrap article-grid"><article class="prose">{body}<h2>Scope and limitations</h2><p>{limit}</p><div class="actions"><a class="button secondary" href="work.html">← All work samples</a><a class="text-link" href="contact.html">Discuss this work ↗</a></div></article><aside class="aside"><h2>At a glance</h2><dl><dt>Work type</dt><dd>{kind}</dd><dt>Reporting focus</dt><dd>{outputs}</dd><dt>Evidence boundary</dt><dd>This page summarises the method. Underlying project files are not distributed through this website.</dd></dl></aside></div>')
case('close-pack.html','Sustainability reporting close pack','A controlled route from environmental KPI inputs to a documented release decision.','''<h2>The reporting problem</h2><p>A complete-looking KPI can still have unresolved evidence, reconciliation or approval gaps. The reporting process needs to expose those gaps before release.</p><h2>The approach</h2><p>The independent close-pack workflow covers eight illustrative environmental KPIs across Scope 1, Scope 2, Scope 3 purchased goods and services, energy, water and waste. Each KPI is linked to an owner, source, evidence reference and approval status.</p><h2>Controls that make a difference</h2><div class="table-scroll"><table><caption class="small">Control design described in the portfolio strategy</caption><thead><tr><th scope="col">Control</th><th scope="col">Review question</th></tr></thead><tbody><tr><td>Completeness and unique IDs</td><td>Are required inputs present, with one identifiable record per KPI?</td></tr><tr><td>Numerical and range checks</td><td>Are values valid, with percentages within the permitted range?</td></tr><tr><td>Evidence and dates</td><td>Are references and dates consistently structured?</td></tr><tr><td>Movement review</td><td>Have material changes been explained?</td></tr><tr><td>Approval status</td><td>Are unresolved exceptions visible to the reviewer?</td></tr></tbody></table></div><h2>Reviewable outputs</h2><p>An exception log and management summary make unresolved issues visible. The reporting design connects findings to follow-up actions and a review decision.</p><div class="note">Control score and release status answer different questions. A high score does not authorise release when a critical exception remains unresolved.</div><h2>Why it matters</h2><p>The workflow shows how reporting checks can support an accountable close: defined inputs, traceable exceptions and a decision that a reviewer can challenge.</p>''','Independent portfolio project · 2026','KPI validation · Exceptions · Review status','Illustrative data and independent portfolio work. This is not an operational client reporting cycle or an assurance opinion. The case study does not assert a current validation score or release status.')
case('interoperability.html','Standards into reporting controls','Translating a disclosure requirement into a structured, reviewable question specification.','''<h2>The reporting problem</h2><p>A requirement is difficult to apply consistently when the datapoint, reporting boundary, evidence expectations and validation rules remain implicit.</p><h2>The prototype approach</h2><p>The work sample structures a chain from source requirement to datapoint, question, guidance, evidence, validation, exception, reviewer decision and controlled change.</p><div class="method-steps"><div><span>01</span>Requirement</div><div><span>02</span>Datapoint</div><div><span>03</span>Guidance</div><div><span>04</span>Validation</div><div><span>05</span>Review</div></div><h2>Example decision rules</h2><details open><summary>Missing is not the same as zero</summary><p>A missing datapoint stays an information gap. Recording zero requires a defined basis and supporting evidence.</p></details><details><summary>A nil adjustment needs support</summary><p>The reviewer should be able to see the reconciliation and rationale supporting a decision that no adjustment is needed.</p></details><details><summary>Critical exceptions constrain approval</summary><p>An approved reporting status should not coexist with an unresolved critical exception. The exception, owner and resolution should remain visible.</p></details><h2>Reporting relevance</h2><p>The method connects interpretation to consistent data collection and review. It also makes the assumptions behind a mapping explicit, including where requirements overlap and where they differ.</p>''','Independent technical work sample','Question specifications · Guidance · Validation rules','This is a prototype methodology, not an official crosswalk or standard-setter product. It does not represent official CDP content or demonstrate equivalence between reporting frameworks. The source implementation is not attached to this preview.')
case('research.html','Corporate disclosure research','Structured interpretation, traceable sources and documented judgement.','''<h2>Research context</h2><p>As a Doctoral Researcher at Oxford Brookes University from September 2019 to September 2025, I examined corporate sustainability disclosure, reporting quality and comparability.</p><p>The research evidence base covered approximately 500 corporate reports and related disclosure materials, including annual reports, sustainability reports and regulatory disclosures.</p><h2>A repeatable methodology</h2><p>I designed and applied a GRI-mapped, four-level coding and scoring framework, with defined classifications, source references and documented judgements.</p><ul><li>Defined inclusion and classification rules to support consistent interpretation.</li><li>Investigated missing, ambiguous and non-comparable information.</li><li>Maintained traceability from source disclosures to item-level assessments and aggregate findings.</li><li>Used Excel, Atlas.ti and Power BI to organise evidence and compare reporting practices.</li></ul><h2>Relevance to sustainability reporting</h2><p>The work developed practical capabilities in evidence synthesis, methodology documentation, data quality and transparent limitations. These are relevant when reporting judgements need to be revisited or challenged.</p><div class="note">“Approximately 500” describes corporate reports and related disclosure materials. It is not a count of companies or an audited inventory.</div><h2>Research award</h2><p>Master of Philosophy, Oxford Brookes University, awarded August 2025. “Doctoral Researcher” describes the research role; it is not a claim to an awarded PhD.</p>''','Research · Oxford Brookes University','GRI-mapped classification · Source traceability · Comparative analysis','This page summarises the research method, not the full thesis or underlying corpus. The visual diagrams illustrate the methodology and do not represent research findings.')
case('b-corp.html','B Corp impact reporting controls','A public-source reconstruction of the reporting process behind impact disclosures.','''<h2>The reporting problem</h2><p>Published impact information can provide useful headline measures without enough detail to re-perform the calculation or confirm the reporting boundary.</p><h2>The work sample</h2><p>Using Oxford HR’s 2024 Impact Report as the public source, I reconstructed an impact-reporting control approach covering customers, workforce, community and environment.</p><p>The work defines KPI calculation bases, proposed owners and evidence requirements, and records qualifications where comparatives or methodology remain unclear.</p><h2>The evidence chain</h2><div class="method-steps"><div><span>01</span>KPI</div><div><span>02</span>Owner</div><div><span>03</span>Calculation</div><div><span>04</span>Evidence</div><div><span>05</span>Qualification</div></div><h2>Reviewable outputs</h2><ul><li>Impact KPI definitions and calculation bases.</li><li>Proposed reporting ownership and evidence requirements.</li><li>Reconciliation of disclosed information.</li><li>Recorded methodology, denominator and comparative gaps.</li></ul><h2>Why ownership matters</h2><p>A public-source reconstruction can propose who should own or review an input. It cannot establish that an organisation has appointed those owners or implemented the controls.</p>''','Independent public-source reconstruction · 2026','Impact KPIs · Proposed ownership · Reporting qualifications','Oxford HR identifies the source report, not a client relationship or endorsement. This work is not B Lab assurance, certification verification or access to internal company records. Proposed controls are recommendations, not observed internal procedures.')
page('standards.html','Standards & Frameworks',heading('Standards & frameworks','From disclosure language<br>to reporting practice.','My focus is on translating requirements into defined datapoints, reporting guidance, validation rules and documented judgements.')+'''<div class="wrap article-grid"><article class="prose"><h2>Knowledge with a clear evidence boundary</h2><div class="table-scroll"><table><thead><tr><th scope="col">Area</th><th scope="col">Basis in my work</th></tr></thead><tbody><tr><td>GRI</td><td>Direct application through the research coding and disclosure-assessment methodology.</td></tr><tr><td>IFRS S1 / S2, SASB, TCFD / TPT, ESRS</td><td>Working knowledge; an interest in how requirements translate into reporting data and controls.</td></tr><tr><td>GHG Protocol</td><td>Working knowledge of Scope 1–3 concepts, supported by independent reporting-control work samples.</td></tr><tr><td>UK sustainability reporting</td><td>A developing professional focus, including the UK SRS landscape. Applicability and effective dates require current source checks.</td></tr></tbody></table></div><h2>My translation method</h2><ol><li><strong>Identify the requirement.</strong> Record the authoritative source, version and scope.</li><li><strong>Define the datapoint.</strong> Specify units, boundary, period and calculation method.</li><li><strong>Assign reporting responsibility.</strong> Identify the data owner and reviewer.</li><li><strong>Design the checks.</strong> Define validation, reconciliation and exception handling.</li><li><strong>Retain the evidence.</strong> Link assumptions and supporting records to the review decision.</li></ol><p class="note">Framework familiarity is distinct from delivered implementation experience. The site does not provide regulatory advice, current applicability assessments or a certified crosswalk.</p><a class="button" href="interoperability.html">Explore the work sample ↗</a></article><aside class="aside"><h2>Questions behind the KPI</h2><p>Where did the number come from?</p><p>Who owns it?</p><p>Which boundary and method apply?</p><p>Can it be reconciled?</p><p>What remains unresolved?</p><p>Who reviewed and signed off?</p></aside></div>''')
page('uk-china.html','UK–China Reporting',heading('Developing professional specialism','Two languages.<br>One reviewable reporting chain.','Connecting international disclosure requirements with controlled reporting processes across data owners and jurisdictions.')+'''<div class="wrap article-grid"><article class="prose"><h2>The reporting challenge</h2><p>When source data, reporting owners and disclosure requirements sit in different jurisdictions, a consistent number depends on shared definitions and a documented method.</p><p>My interest is in the reporting-control challenges facing Chinese and China-linked businesses operating internationally: translating the required datapoint into a clear request, retaining the evidence and making exceptions visible to reviewers.</p><h2>The background I bring</h2><div class="tags"><span>Mandarin & English</span><span>Accounting & finance</span><span>China financial services</span><span>UK disclosure research</span></div><p>My financial-services experience in Shenzhen and Hong Kong involved financial information, client documentation and communication across professional stakeholders. UK research added structured sustainability-disclosure review and methodology development.</p><h2>A practical reporting chain</h2><ol><li>Define the disclosure requirement and reporting boundary.</li><li>Identify the UK or China data owner and source record.</li><li>Document methodology, assumptions and translation choices.</li><li>Reconcile the calculation and retain the supporting evidence.</li><li>Resolve exceptions and record reviewer approval.</li></ol><p class="note">This is a developing specialism informed by my background and independent work. It is not presented as previously delivered cross-border sustainability advisory work.</p><a class="button" href="contact.html">Discuss this focus ↗</a></article><aside class="aside"><p class="eyebrow">Cross-border, consistent process</p><h2>Define.<br>Translate.<br>Reconcile.<br>Review.</h2><p>The objective is a reporting trail that both the data owner and the reviewer can follow.</p></aside></div>''')
page('about.html','About & Experience',heading('About','Accounting discipline.<br>Sustainability focus.','My work sits at the intersection of sustainability disclosure, data quality and reporting controls.')+'''<div class="wrap article-grid"><article class="prose"><h2>Professional focus</h2><p>I am an accounting-and-finance-trained sustainability reporting analyst based in Oxford. I bring together research in corporate sustainability disclosure, recurring financial-services reporting and independent work on reporting controls.</p><p>I focus on the infrastructure behind dependable information: defined requirements, accountable data owners, traceable sources, documented methodology, reconciliation and review.</p><h2>Research and experience</h2><div class="timeline"><article><p class="small">September 2019 – September 2025 · Oxford</p><h3>Doctoral Researcher · Oxford Brookes University</h3><p>Structured, GRI-mapped review of approximately 500 corporate reports and related disclosure materials, with source traceability and documented judgements.</p></article><article><p class="small">September 2015 – July 2017 · Shenzhen</p><h3>Account Manager · Jinniu Capital Ltd</h3><p>Weekly updates and monthly reporting packs for institutional clients; completeness and consistency checks, missing-input follow-up and stakeholder coordination.</p></article><article><p class="small">March 2014 – August 2015 · Shenzhen & Hong Kong</p><h3>Financial Advisor · Zhongjin Capital Ltd</h3><p>Financial and market research, Excel analysis, presentations and structured documentation supporting cross-border engagements.</p></article></div><h2>Education</h2><ul><li>Master of Philosophy · Oxford Brookes University · Awarded August 2025.</li><li>MSc Accounting and Finance · Oxford Brookes University.</li><li>Certificate in Corporate Sustainability · University of Oxford · November 2022 – June 2023.</li></ul><h2>Tools and methods</h2><p>Excel, Power BI and Atlas.ti for research and analysis; working Python for independent portfolio development. KPI dictionaries, reconciliations, evidence registers, exception logs and review/sign-off tracking.</p><a class="button secondary" href="cv.html">View public CV ↗</a></article><aside class="aside"><h2>What connects the work</h2><p>Information should be capable of being questioned, traced and reviewed.</p><dl><dt>Based in</dt><dd>Oxford, United Kingdom</dd><dt>Languages</dt><dd>English and Mandarin Chinese</dd><dt>Role interests</dt><dd>Sustainability reporting, ESG data, standards and assurance readiness</dd></dl></aside></div>''')
page('contact.html','Contact',heading('Contact','Let’s discuss the<br>reporting behind the results.','For sustainability reporting, ESG data, reporting controls and assurance-readiness opportunities.')+'''<div class="wrap article-grid"><div><div class="contact-box"><p class="eyebrow">Email</p><h2>A direct conversation.</h2><p><a href="mailto:sustainabilitypro2026@gmail.com">sustainabilitypro2026@gmail.com ↗</a></p><p class="small">Opens your email application.</p></div><div class="contact-box"><p class="eyebrow">Professional profile</p><h2>Connect on LinkedIn.</h2><a href="https://www.linkedin.com/in/min-gao-39667a44/" rel="noopener noreferrer" target="_blank">View LinkedIn profile ↗</a><p class="small">Opens in a new tab.</p></div></div><aside class="aside"><h2>At a glance</h2><p>Oxford, United Kingdom</p><p>English · Mandarin Chinese</p><a class="text-link" href="cv.html">View public CV ↗</a><hr><p class="small">This website uses no analytics, advertising trackers, cookies or contact-form storage.</p></aside></div>''')
cvbody='''<div class="wrap cv"><div class="page-hero"><p class="eyebrow">Public professional CV</p><h1>Min Gao</h1><p class="lead">Sustainability Reporting | ESG Data | Reporting Controls & Assurance Readiness</p><p>Oxford, UK · <a href="mailto:sustainabilitypro2026@gmail.com">sustainabilitypro2026@gmail.com</a><br><a href="https://www.linkedin.com/in/min-gao-39667a44/">linkedin.com/in/min-gao-39667a44</a></p><div class="actions"><a class="button" href="assets/Min-Gao-CV.html" download>Download CV (HTML) ↓</a></div><p class="small">Print-ready HTML. To save as PDF, use your browser’s Print → Save as PDF.</p></div><article class="prose section"><h2>Profile</h2><p>Evidence-led sustainability reporting analyst with an accounting and finance background, structured research across approximately 500 corporate reports and related disclosure materials, and recurring financial-services client reporting experience. Focused on data quality, evidence traceability, documented judgement and reporting controls.</p><h2>Research and professional experience</h2><article><h3>Doctoral Researcher · Oxford Brookes University</h3><p class="small">September 2019 – September 2025</p><ul><li>Designed and applied a GRI-mapped, four-level coding and scoring framework.</li><li>Reviewed annual reports, sustainability reports and regulatory disclosures; investigated missing and non-comparable information.</li><li>Maintained source traceability using Excel, Atlas.ti and Power BI.</li></ul></article><article><h3>Account Manager · Jinniu Capital Ltd</h3><p class="small">September 2015 – July 2017</p><p>Prepared weekly updates and monthly institutional-client reporting packs. Checked Excel schedules and documentation, coordinated missing inputs and tracked follow-up actions.</p></article><article><h3>Financial Advisor · Zhongjin Capital Ltd</h3><p class="small">March 2014 – August 2015</p><p>Supported cross-border engagements through financial and market research, Excel analysis, presentations and structured client documentation.</p></article><h2>Independent portfolio work</h2><p>Sustainability reporting close-pack design; standards-to-datapoint methodology; B Corp impact-reporting control reconstruction. Independent work samples, not employer or client delivery.</p><h2>Education</h2><p>Master of Philosophy · Oxford Brookes University · Awarded August 2025.<br>MSc Accounting and Finance · Oxford Brookes University.<br>Certificate in Corporate Sustainability · University of Oxford · November 2022 – June 2023.</p><h2>Tools, frameworks and languages</h2><p>Excel · Power BI · Atlas.ti · Working Python.<br>GRI: direct research application. Working knowledge: IFRS S1/S2, SASB, TCFD/TPT, ESRS and GHG Protocol.<br>English and Mandarin Chinese.</p></article></div>'''
page('cv.html','Professional CV',cvbody)
